"""id — quran_b."""

T = {
"quran_081": ("Tentang apa manusia saling bertanya di awal surah An-Naba?", ["Tentang berita yang besar", "Tentang hujan", "Tentang bintang", "Tentang panen"], "«Tentang apa mereka saling bertanya? Tentang berita yang besar»."),
"quran_082": ("Apa arti «Al-Qari'ah», judul surah ke-101?", ["Hari Kiamat yang mengetuk", "Fajar", "Kafilah", "Gunung"], "«Al-Qari'ah! Apakah Al-Qari'ah itu? Dan tahukah kamu apakah Al-Qari'ah itu?»: itu salah satu nama hari kiamat."),
"quran_083": ("Dalam surah Al-Qari'ah, apa yang menanti orang yang timbangannya ringan?", ["Tempat kembalinya adalah Hawiyah (jurang)", "Sebuah taman", "Sebuah mata air", "Sebuah rumah"], "«Dan adapun orang yang ringan timbangannya, maka tempat kembalinya adalah Hawiyah»."),
"quran_084": ("Terhadap apa surah At-Takatsur memperingatkan?", ["Bermegah-megahan dalam memperbanyak, yang melalaikan", "Perjalanan", "Kelaparan", "Diam"], "«Bermegah-megahan telah melalaikan kamu, sampai kamu masuk ke dalam kubur»."),
"quran_085": ("Terhadap siapa surah Al-Humazah dibuka dengan «celakalah»?", ["Setiap pengumpat dan pencela", "Musafir", "Orang yang tidur", "Orang miskin"], "«Celakalah bagi setiap pengumpat dan pencela, yang mengumpulkan harta dan menghitungnya!»"),
"quran_086": ("Apa yang surah Quraisy minta dari Quraisy, sebagai balasan perjalanan musim dingin dan musim panas?", ["Menyembah Tuhan Pemilik Rumah ini, yang memberi makan dan rasa aman", "Membangun benteng", "Meninggalkan perdagangan", "Pergi ke Yaman"], "«Maka hendaklah mereka menyembah Tuhan Pemilik Rumah ini, yang telah memberi makan kepada mereka untuk menghilangkan lapar dan mengamankan mereka dari rasa takut»."),
"quran_087": ("Dengan pertanyaan apa surah Asy-Syarh dibuka?", ["«Bukankah Kami telah melapangkan dadamu?»", "«Tidakkah engkau melihat?»", "«Siapa yang menciptakanmu?»", "«Ke mana engkau pergi?»"], "«Bukankah Kami telah melapangkan dadamu?»"),
"quran_088": ("Dengan apa Allah bersumpah di awal surah At-Tin?", ["Demi buah tin, zaitun, gunung Sinai, dan negeri yang aman ini", "Demi malam dan siang", "Demi bintang-bintang", "Demi laut"], "«Demi buah tin dan buah zaitun! Dan demi gunung Sinai! Dan demi negeri yang aman ini!»"),
"quran_089": ("Bagaimana surah At-Tin menggambarkan penciptaan manusia?", ["Dalam bentuk yang sebaik-baiknya", "Lemah dan kecil", "Dari api", "Dari cahaya"], "«Sungguh, Kami telah menciptakan manusia dalam bentuk yang sebaik-baiknya»."),
"quran_090": ("Dengan negeri apa Allah bersumpah di awal surah Al-Balad?", ["Dengan Makkah, tempat Nabi ﷺ tinggal", "Dengan Madinah", "Dengan Baitul Maqdis", "Dengan Thaif"], "«Aku bersumpah dengan negeri ini, dan engkau bertempat tinggal di negeri ini»."),
"quran_091": ("Apa «jalan yang mendaki lagi sukar» yang digambarkan surah Al-Balad?", ["Memerdekakan budak, memberi makan anak yatim atau orang miskin pada hari kelaparan", "Menyeberangi padang pasir", "Mendaki gunung", "Menyeberangi laut"], "«Dan tahukah kamu apakah jalan yang mendaki lagi sukar itu? Yaitu melepaskan perbudakan, atau memberi makan pada hari kelaparan, kepada anak yatim yang ada hubungan kerabat, atau orang miskin yang sangat fakir»."),
"quran_092": ("Dengan apa Allah bersumpah di awal surah Al-Lail?", ["Demi malam apabila menutupi dan siang apabila terang benderang", "Demi laut dan gunung", "Demi tin dan zaitun", "Demi pena"], "«Demi malam apabila menutupi! Demi siang apabila terang benderang! … Sungguh, usahamu memang beraneka macam»."),
"quran_093": ("Dengan perintah apa surah Al-A'la dibuka?", ["«Sucikanlah nama Tuhanmu Yang Mahatinggi»", "«Bacalah»", "«Bangunlah»", "«Dengarlah»"], "«Sucikanlah nama Tuhanmu Yang Mahatinggi»."),
"quran_094": ("Tentang apa awal surah Al-Ghasyiyah berbicara?", ["Tentang peristiwa yang meliputi segalanya: hari kiamat", "Tentang sebuah perjalanan", "Tentang sebuah pasar", "Tentang sebuah peperangan"], "«Sudahkah sampai kepadamu berita tentang hari kiamat yang meliputi?»"),
"quran_095": ("Terhadap makhluk apa surah Al-Ghasyiyah mengajak merenung?", ["Terhadap unta, bagaimana ia diciptakan", "Terhadap singa", "Terhadap elang", "Terhadap ikan"], "«Maka tidakkah mereka memperhatikan unta, bagaimana diciptakan?»"),
"quran_096": ("Dengan apa Allah bersumpah di awal surah Al-Buruj?", ["Demi langit yang mempunyai gugusan bintang", "Demi bumi", "Demi sungai-sungai", "Demi awan"], "«Demi langit yang mempunyai gugusan bintang! Dan demi hari yang dijanjikan!»"),
"quran_097": ("Apa yang dimaksud «At-Tariq», judul surah ke-86?", ["Bintang malam yang menembus", "Pintu", "Jalan", "Guruh"], "«Demi langit dan yang datang pada malam hari! Dan tahukah kamu apakah yang datang pada malam hari itu? Yaitu bintang yang bersinar tajam»."),
"quran_098": ("Peristiwa apa yang digambarkan pembukaan surah Az-Zalzalah?", ["Bumi diguncang dengan guncangannya", "Hujan lebat", "Angin kencang", "Gerhana"], "«Apabila bumi digoncangkan dengan goncangannya, dan bumi telah mengeluarkan beban-beban beratnya»."),
"quran_099": ("Ukuran apa yang ditetapkan akhir surah Az-Zalzalah bagi amal?", ["Seberat zarah, baik kebaikan maupun keburukan", "Satu takaran", "Satu tahun", "Satu tangan"], "«Maka barang siapa mengerjakan kebaikan seberat zarah, niscaya dia akan melihatnya; dan barang siapa mengerjakan kejahatan seberat zarah, niscaya dia akan melihatnya»."),
"quran_100": ("Apa yang dimaksud «Al-'Adiyat», judul surah ke-100?", ["Kuda perang yang berlari kencang terengah-engah", "Angin", "Ombak", "Awan"], "«Demi kuda perang yang berlari kencang terengah-engah! Yang memercikkan bunga api! Yang menyerang pada pagi hari!»"),
"quran_101": ("Bagaimana surah Al-Baqarah menggambarkan Kitab pada ayat keduanya?", ["Kitab yang tidak ada keraguan padanya, petunjuk bagi orang bertakwa", "Kitab sejarah", "Kumpulan syair", "Hanya kitab hukum"], "«Kitab ini tidak ada keraguan padanya; petunjuk bagi mereka yang bertakwa»."),
"quran_102": ("Ayat manakah yang menjanjikan terpeliharanya Az-Zikr yang diturunkan?", ["«Sesungguhnya Kamilah yang menurunkan Az-Zikr, dan Kami pula yang memeliharanya»", "«Tidak ada yang akan membacanya»", "«Ia akan dilupakan»", "«Ia akan disembunyikan»"], "«Sesungguhnya Kamilah yang menurunkan Az-Zikr, dan sesungguhnya Kami benar-benar memeliharanya»."),
"quran_103": ("Argumen apa yang Al-Qur'an ajukan tentang ketiadaan pertentangan di dalamnya?", ["Sekiranya dari selain Allah, mereka akan menemukan banyak pertentangan di dalamnya", "Bahwa ia pendek", "Bahwa ia berbahasa Arab", "Bahwa ia kuno"], "«Tidakkah mereka menadaburi Al-Qur'an? Sekiranya ia bukan dari sisi Allah, pastilah mereka menemukan banyak pertentangan di dalamnya»."),
"quran_104": ("Dengan apa Al-Qur'an menggambarkan pengaruhnya seandainya diturunkan pada sebuah gunung?", ["Gunung itu akan tunduk terpecah belah karena takut kepada Allah", "Ia akan bercahaya", "Ia akan bergerak", "Ia akan menghijau"], "«Sekiranya Kami turunkan Al-Qur'an ini kepada sebuah gunung, pasti kamu akan melihatnya tunduk terpecah belah karena takut kepada Allah»."),
"quran_105": ("Bagaimana Al-Qur'an memerintahkan cara membacanya dalam surah Al-Muzzammil?", ["Perlahan-lahan dan tertib (tartil)", "Secepat mungkin", "Dalam diam", "Dengan nyanyian"], "«Dan bacalah Al-Qur'an itu dengan perlahan-lahan»."),
"quran_106": ("Apa yang harus dilakukan ketika Al-Qur'an dibacakan, menurut surah Al-A'raf?", ["Mendengarkan dan diam", "Menjawab dengan keras", "Keluar", "Menulis"], "«Dan apabila dibacakan Al-Qur'an, maka dengarkanlah dan diamlah, agar kamu mendapat rahmat»."),
"quran_107": ("Apa yang Al-Qur'an perintahkan diucapkan sebelum mulai membacanya?", ["Berlindung kepada Allah dari setan yang terkutuk", "Menghitung ayat", "Mengucapkan wudu dengan keras", "Membaca ayat terakhir"], "«Apabila engkau membaca Al-Qur'an, mohonlah perlindungan kepada Allah dari setan yang terkutuk»."),
"quran_108": ("Untuk apa Kitab diturunkan menurut surah Sad?", ["Agar ayat-ayatnya direnungkan dan orang berakal mengambil pelajaran", "Agar disalin", "Agar dihitung", "Agar disembunyikan"], "«Kitab yang Kami turunkan kepadamu penuh berkah, agar mereka menghayati ayat-ayatnya dan agar orang-orang yang berakal mendapat pelajaran»."),
"quran_109": ("Tantangan apa yang surah Al-Isra ajukan kepada manusia dan jin sekaligus?", ["Membuat yang serupa Al-Qur'an ini, sekalipun saling membantu", "Menembus langit", "Menghitung bintang", "Membangun kota"], "«Katakanlah: sekiranya manusia dan jin berkumpul untuk membuat yang serupa Al-Qur'an ini, mereka tidak akan dapat membuatnya, sekalipun mereka saling membantu»."),
"quran_110": ("Doa apa yang Al-Qur'an ajarkan tentang ilmu?", ["«Ya Tuhanku, tambahkanlah ilmu kepadaku»", "«Ya Tuhanku, berilah aku harta»", "«Ya Tuhanku, panjangkanlah umurku»", "«Ya Tuhanku, bukakanlah jalan bagiku»"], "«Dan katakanlah: Ya Tuhanku, tambahkanlah ilmu kepadaku»."),
"quran_111": ("Bagaimana surah Az-Zumar menggambarkan sebaik-baik perkataan yang diturunkan?", ["Kitab yang serupa lagi berulang, yang membuat kulit bergetar", "Kitab pendek", "Kitab hukum", "Kitab bersyair"], "«Allah telah menurunkan perkataan yang paling baik, yaitu Kitab yang serupa lagi berulang-ulang. Kulit orang-orang yang takut kepada Tuhannya gemetar karenanya»."),
"quran_112": ("Dengan apa Al-Qur'an mengumpamakan kalimat yang baik dalam surah Ibrahim?", ["Dengan pohon yang baik, akarnya kuat dan cabangnya ke langit", "Dengan sungai", "Dengan gunung", "Dengan bintang"], "«Kalimat yang baik seperti pohon yang baik: akarnya kuat dan cabangnya menjulang ke langit; menghasilkan buahnya pada setiap musim»."),
"quran_113": ("Dengan apa surah Ar-Ra'd mengumpamakan yang benar dan yang batil?", ["Dengan buih yang hanyut dan dengan yang bermanfaat bagi manusia lalu tetap tinggal", "Dengan dua gunung", "Dengan dua kota", "Dengan dua kafilah"], "«Adapun buih, akan hilang sebagai sesuatu yang tidak berguna; tetapi yang bermanfaat bagi manusia akan tetap ada di bumi»."),
"quran_114": ("Dengan apa hati menjadi tenteram menurut surah Ar-Ra'd?", ["Dengan mengingat Allah", "Dengan kekayaan", "Dengan perjalanan", "Dengan tidur"], "«Ingatlah, hanya dengan mengingat Allah hati menjadi tenteram»."),
"quran_115": ("Apa yang surah Al-Kahfi katakan tentang tinta untuk menulis kalimat-kalimat Allah?", ["Lautan akan habis sebelum kalimat Tuhannya habis", "Sebuah tempat tinta cukup", "Satu malam cukup", "Tujuh pena cukup"], "«Katakanlah: sekiranya lautan menjadi tinta untuk menulis kalimat-kalimat Tuhanku, niscaya habislah lautan itu sebelum habis kalimat-kalimat Tuhanku»."),
"quran_116": ("Berapa lautan yang menurut surah Luqman pun tidak akan menghabiskan kalimat-kalimat Allah?", ["Tujuh lautan tambahan, dan tetap tidak cukup", "Satu saja", "Tiga", "Dua belas"], "«Dan seandainya pohon-pohon di bumi menjadi pena dan lautan menjadi tinta, ditambah lagi tujuh lautan sesudahnya, niscaya tidak akan habis kalimat-kalimat Allah»."),
"quran_117": ("Bantahan apa yang akan diajukan seandainya Al-Qur'an diturunkan dalam bahasa asing kepada rasul Arab?", ["«Mengapa ayat-ayatnya tidak dijelaskan?»", "«Terlalu pendek»", "«Terlalu panjang»", "«Tidak berjudul»"], "«Dan sekiranya Al-Qur'an Kami jadikan sebagai bacaan dalam bahasa selain Arab, niscaya mereka mengatakan: “Mengapa tidak dijelaskan ayat-ayatnya?”»"),
"quran_118": ("Kepada apa Al-Qur'an memberi petunjuk menurut surah Al-Isra?", ["Kepada jalan yang paling lurus", "Kepada kekayaan", "Kepada kekuasaan", "Kepada istirahat"], "«Sungguh, Al-Qur'an ini memberi petunjuk ke jalan yang paling lurus dan memberi kabar gembira kepada orang mukmin yang mengerjakan kebajikan bahwa mereka akan mendapat pahala yang besar»."),
"quran_119": ("Bagaimana surah Yunus menggambarkan apa yang turun dari Tuhan?", ["Pelajaran, penyembuh bagi apa yang ada di dada, petunjuk dan rahmat", "Sebuah perhitungan", "Sebuah titah raja", "Sebuah perjanjian"], "«Wahai manusia! Sungguh, telah datang kepadamu pelajaran dari Tuhanmu, penyembuh bagi penyakit yang ada dalam dada, petunjuk serta rahmat bagi orang yang beriman»."),
"quran_120": ("Bagaimana surah Al-Baqarah menggambarkan peran Al-Qur'an sebagai pembeda?", ["Petunjuk bagi manusia dan penjelasan mengenai petunjuk itu serta pembeda", "Sebuah buku hitungan", "Kumpulan kisah", "Kitab pidana"], "«Bulan Ramadan adalah bulan yang di dalamnya diturunkan Al-Qur'an, sebagai petunjuk bagi manusia dan penjelasan mengenai petunjuk itu serta pembeda»."),
"quran_121": ("Dengan apa Allah bersumpah di awal surah Qaf?", ["Demi Al-Qur'an yang mulia", "Demi gunung", "Demi angin", "Demi fajar"], "«Qaf. Demi Al-Qur'an yang mulia!»"),
"quran_122": ("Apa yang dimaksud «Al-Mursalat», judul surah ke-77?", ["Yang diutus berturut-turut", "Kafilah", "Bintang-bintang", "Sungai-sungai"], "«Demi yang diutus berturut-turut!»"),
"quran_123": ("Catatan apa yang surah Al-Muthaffifin sebut bagi orang-orang berbakti?", ["'Illiyyin", "Sijjin", "Al-Lauh", "Az-Zabur"], "«Sesungguhnya kitab orang-orang yang berbakti itu berada dalam 'Illiyyin… kitab yang bertulis, yang disaksikan oleh mereka yang didekatkan»."),
"quran_124": ("Dengan peristiwa apa surah Al-Insyiqaq dibuka?", ["Langit yang terbelah", "Laut yang meluap", "Bumi yang menghijau", "Matahari yang terbit"], "«Apabila langit terbelah, dan patuh kepada Tuhannya, dan sudah semestinya patuh»."),
"quran_125": ("Dengan tanda apa surah At-Takwir dibuka?", ["Matahari yang digulung", "Bulan yang terbelah", "Angin yang bertiup", "Guruh"], "«Apabila matahari digulung, dan apabila bintang-bintang berjatuhan»."),
"quran_126": ("Apa yang ayat terakhir surah Al-Baqarah katakan tentang beban yang dipikulkan pada satu jiwa?", ["Allah tidak membebani seseorang melainkan sesuai kesanggupannya", "Setiap jiwa memikul dua kali lipat", "Tidak seorang pun diuji", "Semua beban sama"], "«Allah tidak membebani seseorang melainkan sesuai dengan kesanggupannya»."),
"quran_127": ("Dengan apa Al-Qur'an mengumpamakan infak di jalan Allah?", ["Dengan sebutir biji yang menumbuhkan tujuh tangkai, tiap tangkai seratus biji", "Dengan sebuah batu", "Dengan sebuah sumur", "Dengan sebuah pelita"], "«Perumpamaan orang yang menginfakkan hartanya di jalan Allah seperti sebutir biji yang menumbuhkan tujuh tangkai; pada setiap tangkai ada seratus biji»."),
"quran_128": ("Dengan apa sedekah yang dibatalkan oleh umpatan dan menyakiti diumpamakan?", ["Dengan batu licin berdebu yang ditimpa hujan lebat lalu menjadi bersih", "Dengan pohon berbuah", "Dengan mata air", "Dengan sebuah rumah"], "«Perumpamaannya seperti batu licin yang di atasnya ada debu, kemudian batu itu ditimpa hujan lebat, maka tinggallah batu itu licin»."),
"quran_129": ("Dengan apa Al-Qur'an mengumpamakan amal orang kafir dalam surah An-Nur?", ["Dengan fatamorgana di tanah datar, yang disangka air oleh orang haus", "Dengan gunung", "Dengan hujan", "Dengan taman"], "«Dan orang-orang yang kafir, amal perbuatan mereka seperti fatamorgana di tanah yang datar, yang disangka air oleh orang-orang yang dahaga; tetapi apabila didatangi tidak ada apa pun»."),
"quran_130": ("Pertanyaan apa yang membuka surah Al-'Ankabut setelah huruf terpisah?", ["«Apakah manusia mengira dibiarkan berkata “kami beriman” tanpa diuji?»", "«Di manakah langit?»", "«Siapa menciptakan laut?»", "«Apa yang akan kamu lakukan besok?»"], "«Apakah manusia mengira bahwa mereka akan dibiarkan hanya dengan mengatakan “kami telah beriman” dan mereka tidak diuji?»"),
"quran_131": ("Bagaimana surah Fatir menggambarkan para malaikat pada ayat pertamanya?", ["Utusan bersayap, dua, tiga, atau empat", "Diciptakan dari tanah", "Tak diketahui jumlahnya", "Menyerupai manusia"], "«Segala puji bagi Allah, Pencipta langit dan bumi, yang menjadikan malaikat sebagai utusan bersayap, dua, tiga, dan empat»."),
"quran_132": ("Tanda apa yang surah Ar-Rum sebut tentang pasangan suami istri?", ["Bahwa Dia menjadikan di antara mereka rasa kasih dan sayang", "Bahwa mereka hidup terpisah", "Bahwa mereka bekerja bersama", "Bahwa mereka bepergian"], "«Dan di antara tanda-tanda kekuasaan-Nya ialah Dia menciptakan pasangan-pasangan untukmu dari jenismu sendiri, agar kamu merasa tenteram kepadanya, dan Dia menjadikan di antaramu rasa kasih dan sayang»."),
"quran_133": ("Dua tanda apa yang surah Ar-Rum sebut tepat setelah penciptaan langit dan bumi?", ["Perbedaan bahasa dan warna kulit", "Siang dan malam", "Angin dan hujan", "Laut dan gunung"], "«Dan di antara tanda-tanda kekuasaan-Nya ialah penciptaan langit dan bumi serta perbedaan bahasamu dan warna kulitmu»."),
"quran_134": ("Dari apa Allah menjadikan segala sesuatu yang hidup menurut surah Al-Anbiya?", ["Dari air", "Dari api", "Dari batu", "Dari udara"], "«Dan Kami jadikan segala sesuatu yang hidup berasal dari air. Maka mengapa mereka tidak beriman?»"),
"quran_135": ("Argumen apa yang Al-Qur'an ajukan menentang banyaknya tuhan dalam surah Al-Anbiya?", ["Sekiranya ada tuhan selain Allah, langit dan bumi pasti rusak", "Mereka akan bersembunyi", "Mereka akan diam", "Mereka akan lenyap"], "«Seandainya pada keduanya ada tuhan-tuhan selain Allah, tentu keduanya telah binasa»."),
"quran_136": ("Tiga hal apa yang menurut ayat 16:90 diperintahkan Allah?", ["Berlaku adil, berbuat kebajikan, dan memberi kepada kerabat", "Puasa, salat, dan haji", "Perdagangan, perjalanan, dan tulisan", "Diam, sabar, dan menyendiri"], "«Sesungguhnya Allah menyuruh berlaku adil dan berbuat kebajikan, memberi bantuan kepada kerabat»."),
"quran_137": ("Dari mana keluar minuman beraneka warna yang mengandung obat bagi manusia menurut surah An-Nahl?", ["Dari perut lebah", "Dari laut", "Dari pohon kurma", "Dari mata air gunung"], "«Dari perutnya keluar minuman yang bermacam-macam warnanya, di dalamnya terdapat obat bagi manusia»."),
"quran_138": ("Bagaimana surah Ar-Rahman dibuka?", ["«Yang Maha Pengasih, Yang telah mengajarkan Al-Qur'an»", "«Demi malam»", "«Segala puji bagi Allah»", "«Bacalah»"], "«Yang Maha Pengasih, Yang telah mengajarkan Al-Qur'an, menciptakan manusia, mengajarnya pandai berbicara»."),
"quran_139": ("Menjadi berapa golongan surah Al-Waqi'ah membagi manusia pada hari kiamat?", ["Tiga", "Dua", "Empat", "Tujuh"], "«Dan kamu menjadi tiga golongan: golongan kanan, golongan kiri, dan orang-orang yang paling dahulu beriman»."),
"quran_140": ("Dengan apa Al-Qur'an mengumpamakan mereka yang memikul Taurat tetapi tidak mengamalkannya?", ["Dengan keledai yang membawa kitab-kitab tebal", "Dengan seekor burung", "Dengan sebuah gunung", "Dengan sebuah kapal"], "«Perumpamaan orang-orang yang dibebani Taurat kemudian mereka tidak memikulnya adalah seperti keledai yang membawa kitab-kitab tebal»."),
"quran_141": ("Perempuan manakah yang Al-Qur'an jadikan teladan bagi orang beriman, dengan menyebut permohonannya akan rumah di sisi Allah?", ["Istri Firaun", "Ratu Saba", "Istri Nuh", "Istri Lut"], "«Dan Allah membuat perumpamaan bagi orang-orang yang beriman, istri Firaun, ketika dia berkata: “Ya Tuhanku, bangunkanlah untukku sebuah rumah di sisi-Mu dalam surga”»."),
"quran_142": ("Dengan nama lain apa surah Al-Ikhlas sering dikenal, karena temanya?", ["Surah tauhid", "Surah perjalanan", "Surah cahaya", "Surah rampasan"], "Al-Ikhlas, «kemurnian», juga disebut surah tauhid, karena menggambarkan Allah sebagai Yang Maha Esa."),
"quran_143": ("Apa yang dinafikan ayat ketiga surah Al-Ikhlas?", ["Bahwa Dia beranak atau diperanakkan", "Bahwa Dia berkuasa", "Bahwa Dia mendengar", "Bahwa Dia mencipta"], "«Dia tidak beranak dan tidak pula diperanakkan»."),
"quran_144": ("Dari apa surah An-Nas memohon perlindungan?", ["Dari bisikan setan yang bersembunyi, dari golongan jin dan manusia", "Dari badai", "Dari penyakit", "Dari kemiskinan"], "«…dari kejahatan bisikan setan yang bersembunyi, yang membisikkan ke dalam dada manusia, dari golongan jin dan manusia»."),
"quran_145": ("Berapa keburukan berbeda yang surah Al-Falaq sebut setelah «kejahatan makhluk-Nya»?", ["Tiga: malam yang gelap, para peniup pada buhul, dan pendengki", "Satu", "Lima", "Tujuh"], "«…dari kejahatan malam apabila telah gelap gulita, dari kejahatan para peniup pada buhul-buhul, dan dari kejahatan orang yang dengki apabila dia dengki»."),
"quran_146": ("Ayat manakah dari Al-Fatihah yang mengungkapkan inti ibadah dan permohonan pertolongan?", ["«Hanya kepada Engkaulah kami menyembah dan hanya kepada Engkaulah kami memohon pertolongan»", "«Segala puji bagi Allah»", "«Tunjukilah kami»", "«Pemilik hari pembalasan»"], "«Hanya kepada Engkaulah kami menyembah dan hanya kepada Engkaulah kami memohon pertolongan»."),
"quran_147": ("Dengan permohonan apa surah Al-Fatihah ditutup?", ["Ditunjuki jalan yang lurus, jalan orang-orang yang diberi nikmat", "Kekayaan", "Kemenangan", "Umur panjang"], "«Tunjukilah kami jalan yang lurus, yaitu jalan orang-orang yang telah Engkau beri nikmat»."),
"quran_148": ("Dua jenis ayat apa yang dibedakan surah Ali 'Imran?", ["Ayat muhkamat dan ayat mutasyabihat", "Yang panjang dan yang pendek", "Yang Makkiyah dan yang Madaniyah", "Yang dibaca dan yang ditulis"], "«Dialah yang menurunkan Kitab kepadamu: di antaranya ada ayat-ayat yang muhkamat, itulah pokok-pokok Kitab, dan yang lain mutasyabihat»."),
"quran_149": ("Prinsip apa yang ayat 2:106 tetapkan tentang ayat yang diganti?", ["Allah mendatangkan yang lebih baik atau yang sebanding", "Dihapus tanpa pengganti", "Dilupakan", "Ditulis ulang oleh manusia"], "«Ayat yang Kami batalkan atau Kami hilangkan dari ingatan, pasti Kami ganti dengan yang lebih baik atau yang sebanding dengannya»."),
"quran_150": ("Apa yang akan Rasul ﷺ adukan kepada Tuhannya menurut surah Al-Furqan?", ["Bahwa kaumnya menjadikan Al-Qur'an ini terabaikan", "Bahwa dia lelah", "Bahwa dia sendirian", "Bahwa dia miskin"], "«Dan Rasul berkata: “Ya Tuhanku, sesungguhnya kaumku telah menjadikan Al-Qur'an ini terabaikan”»."),
}
